/*
 * SCENE_CHAR.C  Scene character scripts
 *
 * Scripts for the select screen, general effects (etc, etc2, etc3), direct_03, eff09, the endings and the opening; eff64_stepxy_table is eff64's step table.
 * bg_scrn_data_00 and bg_scrn_data_02, stored after op_char_table_012, are the cell maps of stage
 * backgrounds 0 and 2 (bg_cg_src_tbl), in the layout of SCRN_DATA.C.
 * Each *_char_table is an index of animation scripts ending in 0 followed by the scripts, in the
 * format of the fighters' tables: an effect's work takes the table as its char_table and
 * set_char_move_init starts its scripts. See charscr.h for the line layouts.
 */

